UPDATE public.configuracoes SET modelo_html = '<p style="text-align:justify;font-family:Times New Roman,serif;font-size:9pt"><em><strong>Missão:</strong> Contribuir para o desenvolvimento humano e socioeconômico da região do semi-árido nordestino, através da formação de profissionais aptos ao permanente autodesenvolvimento técnico, intelectual e ético.</em></p><hr /><p style="font-family:Times New Roman,serif;font-size:12pt">{{numero}}</p><p style="text-align:right;font-family:Times New Roman,serif;font-size:12pt"><strong>{{cidade}}, {{data}}.</strong></p><p style="font-family:Times New Roman,serif;font-size:12pt">&nbsp;</p><p style="font-family:Times New Roman,serif;font-size:12pt">{{destinatario}}</p><p style="font-family:Times New Roman,serif;font-size:12pt">&nbsp;</p><p style="font-family:Times New Roman,serif;font-size:12pt">Prezado (a) Secretário (a),</p><p style="text-align:justify;font-family:Times New Roman,serif;font-size:12pt">A Coordenação de Estágios da Faculdade de Ciências Humanas e Exatas do Sertão do São Francisco – FACESF, localizada em Belém do São Francisco – PE, apresenta a Vossa Senhoria o aluno (a) <strong>{{nome}}</strong> CPF <strong>{{cpf}}</strong> regularmente matriculado (a) no curso de {{curso}} da supracitada IES, matrícula: {{matricula}}, e solicita, para o mesmo, a realização de Estágio Curricular Obrigatório.</p><p style="text-align:justify;font-family:Times New Roman,serif;font-size:12pt">O estágio transcorrerá na área de {{area_estagio}}, sob a orientação do professor (a) {{professor_orientador}}, {{registro_professor}}, com carga horária de {{carga_horaria}} distribuídas entre os meses de {{periodo}}, ajustando-se ao plano de estágio concebido pelo (a) estagiário (a) sob acordos entre os profissionais responsáveis – professor orientador e supervisor de campo.</p><p style="text-align:justify;font-family:Times New Roman,serif;font-size:12pt">Informamos que o aluno será encaminhado com o Termo de Compromisso, Seguro Contra Acidentes Pessoais pela Seguradora {{seguradora}}, sob a apólice Nº {{apolice}}.</p><p style="text-align:justify;font-family:Times New Roman,serif;font-size:12pt">Na ocasião, manifestamos nossos votos de estima e apreço, agradecemos o esforço em nos atender e nos colocamos à disposição para quaisquer esclarecimentos adicionais que se fizerem necessários.</p><p style="font-family:Times New Roman,serif;font-size:12pt">&nbsp;</p><p style="text-align:center;font-family:Times New Roman,serif;font-size:12pt">Atenciosamente,</p><p style="text-align:center;font-family:Times New Roman,serif;font-size:12pt">&nbsp;</p><p style="text-align:center;font-family:Times New Roman,serif;font-size:12pt"><strong>{{coordenador}}</strong></p><p style="text-align:center;font-family:Times New Roman,serif;font-size:11pt">{{cargo_coordenador}}</p>', updated_at = now();